  Future<void> _pickDate(TextEditingController controller) async {
    final picked = await showDatePicker(
      context: context,
      initialDate: DateTime.now(),
      firstDate: DateTime(2020),
      lastDate: DateTime.now().add(const Duration(days: 365)),
      builder: (ctx, child) => Theme(
        data: Theme.of(ctx).copyWith(
          colorScheme:
              const ColorScheme.light(primary: AppConstants.primaryBlue),
        ),
        child: child!,
      ),
    );
    if (picked != null) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).clearSnackBars();
      setState(() {
        controller.text =
            '${picked.day.toString().padLeft(2, '0')}/${picked.month.toString().padLeft(2, '0')}/${picked.year}';
      });
      _formKey.currentState?.validate();
    }
  }

  Future<void> _pickTime({
    required String currentVal,
    required ValueChanged<String> onSelected,
  }) async {
    TimeOfDay initialTime = TimeOfDay.now();
    if (currentVal.contains(':')) {
      final parts = currentVal.split(':');
      final h = int.tryParse(parts[0]);
      final m = int.tryParse(parts[1]);
      if (h != null && m != null) {
        initialTime = TimeOfDay(hour: h, minute: m);
      }
    }

    final picked = await showTimePicker(
      context: context,
      initialTime: initialTime,
      builder: (ctx, child) => Theme(
        data: Theme.of(ctx).copyWith(
          colorScheme: const ColorScheme.light(
            primary: AppConstants.primaryBlue,
            onPrimary: Colors.white,
            onSurface: Color(0xFF0F172A),
          ),
        ),
        child: child!,
      ),
    );

    if (picked != null) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).clearSnackBars();
      final hh = picked.hour.toString().padLeft(2, '0');
      final mm = picked.minute.toString().padLeft(2, '0');
      setState(() {
        onSelected('$hh:$mm');
      });
      _formKey.currentState?.validate();
    }
  }

  void _addMisaItem() {
    if (_tanggalMisaController.text.isEmpty) {
      _showError('Tanggal misa wajib diisi.');
      return;
    }
    if (_alamatMisaController.text.trim().isEmpty) {
      _showError('Alamat lokasi misa wajib diisi.');
      return;
    }

    // Parse Jam Mulai & Jam Akhir Misa
    final startParts = _jamMulaiMisa.split(':');
    final endParts = _jamAkhirMisa.split(':');
    final startM = (int.tryParse(startParts[0]) ?? 0) * 60 + (int.tryParse(startParts[1]) ?? 0);
    final endM = (int.tryParse(endParts[0]) ?? 0) * 60 + (int.tryParse(endParts[1]) ?? 0);

    if (endM <= startM) {
      _showError('Jam akhir misa harus lebih besar dari jam mulai misa.');
      return;
    }

    final parts = _tanggalMisaController.text.split('/');
    final formattedDate = parts.length == 3
        ? '${parts[2]}-${parts[1]}-${parts[0]}'
        : _tanggalMisaController.text;

    final item = OrderItem(
      itemName: _selectedJenisMisa,
      scheduledDate: formattedDate,
      scheduledTimeStart: _jamMulaiMisa,
      scheduledTimeEnd: _jamAkhirMisa,
      locationName: _alamatMisaController.text.trim(),
    );

    setState(() {
      _misaList.add(item);
      _alamatMisaController.clear();
    });

    ScaffoldMessenger.of(context).clearSnackBars();
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('Misa "${item.itemName}" berhasil ditambahkan!'),
        backgroundColor: Colors.green.shade700,
        behavior: SnackBarBehavior.floating,
        duration: const Duration(seconds: 2),
      ),
    );
  }

  int _urgensiToId(String label) {
    if (label.contains('Sangat')) return 3;
    if (label.contains('Penting')) return 2;
    return 1;
  }

  Color _getUrgensiColor(String label) {
    if (label.contains('Sangat')) return Colors.red.shade700;
    if (label.contains('Penting')) return Colors.amber.shade800;
    return Colors.blue.shade700;
  }

  Future<void> _submit() async {
    setState(() {
      _autovalidateMode = AutovalidateMode.onUserInteraction;
    });

    if (!_formKey.currentState!.validate()) {
      _showError('Harap lengkapi semua kolom wajib dengan benar.');
      return;
    }

    // Auto-add current configured Misa item if list is empty but inputs are filled
    if (_misaList.isEmpty) {
      if (_alamatMisaController.text.trim().isNotEmpty) {
        _addMisaItem();
      }
    }

    if (_misaList.isEmpty) {
      _showError('Harap tambahkan minimal 1 Jadwal Pelayanan Misa Kedukaan.');
      return;
    }

    setState(() => _isLoading = true);

    final firstMisa = _misaList.first;
    final notes = [
      'Nama Almarhum: ${_namaMeninggalController.text}',
      'Hubungan: $_selectedHubungan',
      'Tgl Meninggal: ${_tanggalMeninggalController.text}',
      'Waktu Meninggal: $_waktuMeninggal',
      'Jumlah Misa: ${_misaList.length} sesi',
      if (_catatanController.text.isNotEmpty)
        'Catatan: ${_catatanController.text}',
    ].join(' | ');

    final res = await ApiService.createOrder(
      serviceCategoryId: 2, // 2 = Misa Kedukaan
      urgencyLevelId: _urgensiToId(_selectedUrgensi),
      scheduledDate: firstMisa.scheduledDate,
      scheduledTime: firstMisa.scheduledTimeStart,
      locationName: firstMisa.locationName,
      addressDetail: firstMisa.locationName,
      notes: notes,
      attachmentUrl: _attachmentUrl,
      items: _misaList,
      userId: widget.userId,
      keuskupanId: _isSameParish ? null : _selectedKeuskupanId,
      parokiId: _isSameParish ? null : _selectedParokiId,
      kabupatenKotaId: _isSameParish ? null : _selectedKabupatenKotaId,
    );

    setState(() => _isLoading = false);
    if (!mounted) return;

    final bool isSuccess =
        res['message']?.toString().toLowerCase().contains('gagal') != true;

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Row(
          children: [
            Icon(
              isSuccess
                  ? Icons.check_circle_outline_rounded
                  : Icons.error_outline_rounded,
              color: Colors.white,
            ),
            const SizedBox(width: 10),
            Expanded(
              child: Text(
                res['message'] ?? 'Permintaan Misa Kedukaan berhasil dikirim',
                style: const TextStyle(fontWeight: FontWeight.w600),
              ),
            ),
          ],
        ),
        backgroundColor: isSuccess ? Colors.green.shade700 : Colors.red.shade700,
        behavior: SnackBarBehavior.floating,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
        margin: const EdgeInsets.all(16),
      ),
    );

    if (isSuccess) {
      Navigator.pop(context);
    }
  }

  void _showError(String msg) {
    ScaffoldMessenger.of(context).clearSnackBars();
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(msg),
        backgroundColor: Colors.red.shade700,
        behavior: SnackBarBehavior.floating,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
        margin: const EdgeInsets.all(16),
        duration: const Duration(seconds: 3),
      ),
    );
  }

